const item = $('Code in JavaScript').first().json;
const allExtractions = $input.all();
const MAX_PER_PDF = 4000;
const MAX_TOTAL_PDF_TEXT = 12000;
const pdfTexts = allExtractions
  .map(function (inp) {
    const j = inp.json || {};
    return (j.text || j.data || '').toString().trim().slice(0, MAX_PER_PDF);
  })
  .filter(function (t) {
    return t.length > 0;
  });
const pdfText = pdfTexts.join('\n\n--- next attached PDF ---\n\n').slice(0, MAX_TOTAL_PDF_TEXT);
const pdfAttachmentCount = item.pdfAttachmentCount || 0;
const pdfExtractionWarning =
  pdfAttachmentCount > 0 && pdfTexts.length < pdfAttachmentCount
    ? pdfTexts.length + ' of ' + pdfAttachmentCount + ' attached PDF(s) had no extractable text (likely a scanned image with no text layer) - double-check the extraction below.'
    : null;
const emailText =
  'From: ' +
  (item.mimeFrom || '') +
  '\nSubject: ' +
  (item.subject || '') +
  '\n\n' +
  (item.bodyPreview || '') +
  (pdfText ? '\n\n--- Attached PDF itinerary (text extract) ---\n' + pdfText : '');
const systemPrompt =
  'You extract structured travel booking data from an email, optionally with an attached PDF itinerary appended after it. Return null for any field not present in the source - never invent data.\n\nbooking_type classification, in order of precedence:\n- flight: has an airline name, a flight number, or a departure/arrival airport.\n- lodging: has a hotel, resort, Airbnb, or check-in/check-out date - even if it also mentions a city or airport nearby.\n- cruise: a cruise line booking (Royal Caribbean, Carnival, etc), usually multi-day with several ports of call.\n- rental_car: a car rental agency (Hertz, Avis, Enterprise, etc).\n- transit: ground or short-hop water transport between cities that is NOT a flight, rental car, or cruise - train, bus, ferry.\n- restaurant: a dining reservation.\n- activity: a tour, ticket, or event booking.\n- general: anything else, including newsletters and emails with no booking details.\n\nIATA or station codes go in the _code fields; the human-readable name goes in the _name fields. For lodging, destination_name/destination_code refer to the hotel\'s city, not the hotel itself - the hotel name goes in provider_name. Dates must be ISO-8601 (YYYY-MM-DDTHH:mm:ss) when a date is present in the source; if only a date with no time is given, use T00:00:00. If a year is not stated, infer it from context (e.g. a date later than any date already mentioned) rather than defaulting to the current year.\n\nFor lodging bookings, capture any room type, bed configuration, or smoking preference mentioned in the source (e.g. "2 Queen Beds, Non-Smoking") in the notes field - never invent one if it is not stated.\n\nFor cruise bookings: start_datetime/end_datetime are the embarkation/disembarkation date and time. Populate the stops array with every port of call in visit order, including embarkation and disembarkation as the first and last entries - skip pure sea/cruising days that have no port. Each stop needs a name and a date (YYYY-MM-DD). For all other booking types, leave stops empty.\n\ntotal_amount is the single total amount actually charged or due for this booking (the number next to "Total", "Amount Charged", "Grand Total", or similar) - never a per-night/per-person rate, a subtotal before taxes/fees, a "starting from" marketing price, or a loyalty-points value. Leave it null if no total is stated. currency is the ISO-4217 3-letter code for that amount, inferred from a currency symbol or code in the source ($/USD, €/EUR, £/GBP, etc) - null if total_amount is null or the currency cannot be determined.';
const schema = {
  type: 'object',
  properties: {
    booking_type: { type: 'string', enum: ['flight', 'lodging', 'rental_car', 'transit', 'cruise', 'restaurant', 'activity', 'general'] },
    confirmation_code: { type: ['string', 'null'] },
    provider_name: { type: ['string', 'null'] },
    start_datetime: { type: ['string', 'null'] },
    end_datetime: { type: ['string', 'null'] },
    origin_name: { type: ['string', 'null'] },
    origin_code: { type: ['string', 'null'] },
    destination_name: { type: ['string', 'null'] },
    destination_code: { type: ['string', 'null'] },
    stops: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          date: { type: ['string', 'null'] },
        },
        required: ['name'],
      },
    },
    notes: { type: ['string', 'null'] },
    total_amount: { type: ['number', 'null'] },
    currency: { type: ['string', 'null'] },
  },
  required: ['booking_type'],
};
const exampleEmail =
  'From: jane@example.com\nSubject: Your Hilton Reservation - Confirmation HH1234\n\nThank you for booking the Hilton Garden Inn Austin Downtown.\n\nConfirmation Number: HH1234\nCheck-in: June 3, 2027\nCheck-out: June 5, 2027\nTotal Charged: $450.50';
const exampleAnswer = JSON.stringify({
  booking_type: 'lodging',
  confirmation_code: 'HH1234',
  provider_name: 'Hilton Garden Inn Austin Downtown',
  start_datetime: '2027-06-03T00:00:00',
  end_datetime: '2027-06-05T00:00:00',
  origin_name: null,
  origin_code: null,
  destination_name: 'Austin',
  destination_code: null,
  stops: [],
  notes: null,
  total_amount: 450.5,
  currency: 'USD',
});
const cruiseExample =
  'From: agent@example.com\nSubject: Your Cruise Confirmation - ABC999\n\n--- Attached PDF itinerary (text extract) ---\nCruise Confirmation\nConfirmation: ABC999\nRoyal Caribbean\nEmbark: May 1, 2028\nDisembark: May 5, 2028\nDay 1: Miami, Florida - May 1, 2028 | Depart 06:00 PM\nDay 2: Cruising - May 2, 2028\nDay 3: Nassau, Bahamas - May 3, 2028 | 08:00 AM To 05:00 PM\nDay 4: CocoCay, Bahamas - May 4, 2028 | 08:00 AM To 04:00 PM\nDay 5: Miami, Florida - May 5, 2028 | Arrive 06:00 AM';
const cruiseAnswer = JSON.stringify({
  booking_type: 'cruise',
  confirmation_code: 'ABC999',
  provider_name: 'Royal Caribbean',
  start_datetime: '2028-05-01T18:00:00',
  end_datetime: '2028-05-05T06:00:00',
  origin_name: null,
  origin_code: null,
  destination_name: null,
  destination_code: null,
  stops: [
    { name: 'Miami, Florida', date: '2028-05-01' },
    { name: 'Nassau, Bahamas', date: '2028-05-03' },
    { name: 'CocoCay, Bahamas', date: '2028-05-04' },
    { name: 'Miami, Florida', date: '2028-05-05' },
  ],
  notes: null,
  total_amount: null,
  currency: null,
});
const helpers = this.helpers;

async function withRetry(fn, attempts, baseDelayMs) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (e) {
      lastErr = e;
      if (i < attempts - 1) {
        await new Promise(function (resolve) {
          setTimeout(resolve, baseDelayMs * Math.pow(2, i));
        });
      }
    }
  }
  throw lastErr;
}

let extracted = null;
let extractionError = null;
try {
  const response = await withRetry(
    function () {
      return helpers.httpRequest({
        method: 'POST',
        url: 'http://ollama.ai.svc.cluster.local:11434/api/chat',
        body: {
          model: 'mistral:latest',
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: exampleEmail },
            { role: 'assistant', content: exampleAnswer },
            { role: 'user', content: cruiseExample },
            { role: 'assistant', content: cruiseAnswer },
            { role: 'user', content: emailText },
          ],
          stream: false,
          format: schema,
        },
        json: true,
        timeout: 240000,
      });
    },
    3,
    2000
  );
  try {
    extracted = JSON.parse(response.message.content);
  } catch (e) {
    extracted = { booking_type: 'general', parse_error: String(e) };
  }

  const knownBookingTypes = schema.properties.booking_type.enum;
  let validationError = null;
  if (extracted.parse_error) {
    validationError = 'Ollama response was not valid JSON: ' + extracted.parse_error;
  } else if (!extracted.booking_type || knownBookingTypes.indexOf(extracted.booking_type) === -1) {
    validationError = 'Ollama returned an unrecognized booking_type: ' + JSON.stringify(extracted.booking_type);
  } else if (extracted.start_datetime && isNaN(new Date(extracted.start_datetime).getTime())) {
    validationError = 'Ollama returned an unparseable start_datetime: ' + JSON.stringify(extracted.start_datetime);
  } else if (extracted.end_datetime && isNaN(new Date(extracted.end_datetime).getTime())) {
    validationError = 'Ollama returned an unparseable end_datetime: ' + JSON.stringify(extracted.end_datetime);
  }
  if (!validationError && extracted.total_amount != null) {
    if (typeof extracted.total_amount !== 'number' || !(extracted.total_amount > 0)) {
      extracted.total_amount = null;
      extracted.currency = null;
    } else if (extracted.currency != null && !/^[A-Za-z]{3}$/.test(extracted.currency)) {
      extracted.currency = null;
    } else if (extracted.currency) {
      extracted.currency = extracted.currency.toUpperCase();
    }
  }
  if (validationError) {
    extractionError = validationError;
  }
} catch (e) {
  extractionError = 'Ollama extraction failed: ' + (e.message || String(e));
}
return [{ json: { ...item, extracted, extractionError, pdfExtractionWarning } }];

const item = $input.first().json;
const ex = item.extracted || {};
const extractionError = item.extractionError || null;
const pdfExtractionWarning = item.pdfExtractionWarning || null;
const helpers = this.helpers;

const TREK_URL = 'http://trek.household.svc.cluster.local:3000/mcp';
const TREK_TOKEN = $env.TREK_API_TOKEN;

function baseHeaders(sessionId) {
  const h = {
    'Authorization': 'Bearer ' + TREK_TOKEN,
    'Content-Type': 'application/json',
    'Accept': 'application/json, text/event-stream',
    'X-Forwarded-Proto': 'https',
    'Host': '${TREK_SUBDOMAIN}.${SECRET_DOMAIN}',
  };
  if (sessionId) h['Mcp-Session-Id'] = sessionId;
  return h;
}

function parseMcpBody(bodyText) {
  const match = bodyText.match(/data:\s*(\{[\s\S]*\})/);
  const jsonText = match ? match[1] : bodyText;
  return JSON.parse(jsonText);
}

async function withRetry(fn, attempts, baseDelayMs) {
  let lastErr;
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (e) {
      lastErr = e;
      if (i < attempts - 1) {
        await new Promise(function (resolve) {
          setTimeout(resolve, baseDelayMs * Math.pow(2, i));
        });
      }
    }
  }
  throw lastErr;
}

async function mcpRpc(sessionId, method, params) {
  // Retry is scoped to this HTTP call only, not to callers - it only fires when the
  // request/response cycle itself fails (pod restart, connection reset), which is the
  // dominant home-lab failure mode. A response Trek actually sent back - success or a
  // JSON-RPC/application error - is never retried, to avoid re-issuing a write Trek may
  // have already applied.
  const res = await withRetry(
    function () {
      return helpers.httpRequest({
        method: 'POST',
        url: TREK_URL,
        headers: baseHeaders(sessionId),
        body: JSON.stringify({ jsonrpc: '2.0', id: Date.now(), method: method, params: params || {} }),
        returnFullResponse: true,
      });
    },
    3,
    1000
  );
  return { parsed: parseMcpBody(String(res.body)), headers: res.headers };
}

async function mcpTool(sessionId, toolName, args) {
  const r = await mcpRpc(sessionId, 'tools/call', { name: toolName, arguments: args || {} });
  if (r.parsed.error) {
    throw new Error('Trek MCP error calling ' + toolName + ': ' + JSON.stringify(r.parsed.error));
  }
  const content = (r.parsed.result && r.parsed.result.content) || [];
  const textPart = content[content.length - 1];
  const raw = textPart ? textPart.text : '{}';
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error('Trek tool ' + toolName + ' returned a non-JSON response: ' + raw);
  }
  return parsed;
}

async function resolveCoords(sessionId, query) {
  if (!query) return null;
  try {
    const searchResult = await mcpTool(sessionId, 'search_place', { query: query });
    const places = searchResult.places || [];
    const best = places[0];
    if (best && best.lat != null && best.lng != null) {
      return { lat: best.lat, lng: best.lng };
    }
  } catch (e) {
    // no match / lookup failure - endpoint will be created without coordinates
  }
  return null;
}

function toDate(s) {
  return s ? new Date(s) : null;
}

function overlaps(aStart, aEnd, bStart, bEnd) {
  if (aStart == null || bStart == null) return false;
  const aE = aEnd != null ? aEnd : aStart;
  const bE = bEnd != null ? bEnd : bStart;
  return aStart <= bE && bStart <= aE;
}

// Trek's Costs tab only recognizes these 14 free-text category labels (anything
// else lands in "Other") - see budget.mcp.js create_budget_item.
const BUDGET_CATEGORY_BY_TYPE = {
  flight: 'Flights',
  lodging: 'Accommodation',
  rental_car: 'Transport',
  transit: 'Transport',
  cruise: 'Transport',
  restaurant: 'Food & drink',
  activity: 'Activities',
  general: 'Other',
};

// create_reservation/create_transport only accept a bare `price` (no currency) -
// it is always booked in the trip's own currency. When the email states a
// different currency, linking through that field would silently misrecord the
// amount, so those cases fall back to a standalone create_budget_item call
// (which does take `currency` and freezes its own FX rate) instead of the
// native "linked" price.
function planCost(ex, tripCurrency) {
  if (typeof ex.total_amount !== 'number' || !(ex.total_amount > 0)) return null;
  const currency = ex.currency ? ex.currency.toUpperCase() : null;
  const linked = !currency || !tripCurrency || currency === tripCurrency.toUpperCase();
  return {
    amount: ex.total_amount,
    currency: currency,
    category: BUDGET_CATEGORY_BY_TYPE[ex.booking_type] || 'Other',
    linked: linked,
  };
}

let tripId = null;
let createdNewTrip = false;
let isDuplicate = false;
let duplicateMatch = null;
let duplicateMatchReason = null;
let createdBooking = null;
let placeSearchNote = null;
let trekError = null;
let costError = null;
let costPlan = null;

if (!extractionError) {
  try {
    const initRes = await mcpRpc(null, 'initialize', {
      protocolVersion: '2024-11-05',
      capabilities: {},
      clientInfo: { name: 'n8n-trip-ingest', version: '1.0' },
    });
    const sessionId = initRes.headers['mcp-session-id'] || initRes.headers['Mcp-Session-Id'];

    const tripsData = await mcpTool(sessionId, 'list_trips', {});
    const trips = tripsData.trips || [];

    const startDt = toDate(ex.start_datetime);
    const endDt = toDate(ex.end_datetime) || startDt;
    const startDateOnly = startDt ? startDt.toISOString().slice(0, 10) : null;
    const endDateOnly = endDt ? endDt.toISOString().slice(0, 10) : startDateOnly;

    let matchedTrip = null;
    if (startDt) {
      const windowMs = 3 * 24 * 60 * 60 * 1000;
      for (const t of trips) {
        const tStart = new Date(t.start_date + 'T00:00:00');
        const tEnd = new Date(t.end_date + 'T23:59:59');
        if (startDt.getTime() >= tStart.getTime() - windowMs && startDt.getTime() <= tEnd.getTime() + windowMs) {
          matchedTrip = t;
          break;
        }
      }
    }

    if (matchedTrip) {
      tripId = matchedTrip.id;
      // A booking can land outside the trip's recorded window (an extra night tacked
      // on, a longer drive home) even though it matched within the +/-3 day fuzz above -
      // keep the trip's own date range accurate so future list_trips window-matching
      // (and the Trek UI) reflects reality instead of just whichever booking created it.
      const curStart = matchedTrip.start_date;
      const curEnd = matchedTrip.end_date;
      const newStart = startDateOnly && (!curStart || startDateOnly < curStart) ? startDateOnly : curStart;
      const newEnd = endDateOnly && (!curEnd || endDateOnly > curEnd) ? endDateOnly : curEnd;
      if (newStart !== curStart || newEnd !== curEnd) {
        await mcpTool(sessionId, 'update_trip', { tripId: tripId, start_date: newStart, end_date: newEnd });
      }
    } else {
      const destName = ex.destination_name || ex.destination_code || ex.provider_name || 'Trip';
      const createArgs = { title: 'Trip to ' + destName, currency: 'USD' };
      if (startDateOnly) createArgs.start_date = startDateOnly;
      if (endDateOnly) createArgs.end_date = endDateOnly;
      const created = await mcpTool(sessionId, 'create_trip', createArgs);
      tripId = created.trip ? created.trip.id : created.id;
      createdNewTrip = true;
    }

    const tripCurrency = matchedTrip ? matchedTrip.currency || 'USD' : 'USD';
    costPlan = planCost(ex, tripCurrency);

    // Only ever called from the non-duplicate creation branch below. Covers two
    // cases: a currency that doesn't match the trip's (create_reservation/
    // create_transport can't take one) and create_accommodation, which has no
    // price field at all - linking through place_id there instead.
    async function recordBudgetItem(name, placeId) {
      try {
        const budgetArgs = { tripId: tripId, name: name, category: costPlan.category, total_price: costPlan.amount };
        if (costPlan.currency) budgetArgs.currency = costPlan.currency;
        if (placeId) budgetArgs.place_id = placeId;
        await mcpTool(sessionId, 'create_budget_item', budgetArgs);
      } catch (e) {
        costError = 'Could not record cost: ' + (e.message || String(e));
      }
    }

    const summary = await mcpTool(sessionId, 'get_trip_summary', { tripId: tripId });
    const days = summary.days || [];

    function findDayId(dateStr) {
      if (!dateStr) return null;
      const day = days.find(function (d) {
        return d.date === dateStr;
      });
      return day ? day.id : null;
    }

    // Trip creation auto-generates days for its own date range, but a booking that
    // lands outside that range (see update_trip above) still needs its own day row -
    // Trek has no bulk "extend days" call, so missing ones are created on demand.
    // Scoped to the non-duplicate branch below so a duplicate never creates orphan days.
    async function ensureDayId(dateStr) {
      if (!dateStr) return null;
      const existing = findDayId(dateStr);
      if (existing != null) return existing;
      const createdDay = await mcpTool(sessionId, 'create_day', { tripId: tripId, date: dateStr });
      const newDay = createdDay.day || createdDay;
      days.push({ id: newDay.id, date: dateStr, day_number: newDay.day_number });
      return newDay.id;
    }

    function timeOnly(isoDateTime) {
      if (!isoDateTime || isoDateTime.length < 16) return null;
      return isoDateTime.slice(11, 16);
    }

    function dayNumberById(id) {
      const d = days.find(function (x) { return x.id === id; });
      return d ? d.day_number : null;
    }

    const existingReservations = summary.reservations || [];
    const existingAccommodations = summary.accommodations || [];

    const isLodging = ex.booking_type === 'lodging';
    const transportTypeMap = { flight: 'flight', transit: 'train', cruise: 'cruise' };
    const expectedTransportType = transportTypeMap[ex.booking_type] || null;

    // A lodging booking that couldn't be matched to a place (no search_place hit) falls
    // back to a plain type:'hotel' reservation instead of an accommodation record (see
    // the creation branch below) - scan both shapes so that downgraded booking is still
    // found as the existing match on a later duplicate email.
    if (ex.confirmation_code) {
      duplicateMatch = isLodging
        ? existingAccommodations.find(function (a) {
            return a.confirmation === ex.confirmation_code;
          }) || existingReservations.find(function (r) {
            return r.type === 'hotel' && r.confirmation_number === ex.confirmation_code;
          })
        : existingReservations.find(function (r) {
            return r.confirmation_number === ex.confirmation_code;
          });
      if (duplicateMatch) duplicateMatchReason = 'matching confirmation number';
    }

    // Confirmation numbers can legitimately differ for the same real booking (travel
    // agency code vs. the airline/cruise line's own code, especially on TripIt-migrated
    // data) - fall back to type + overlapping date window, which a same-trip sender is
    // very unlikely to hit twice for an unrelated booking.
    function normalizeWords(s) {
      return (s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(function (w) { return w.length > 2; });
    }
    function providerNamesRelated(a, b) {
      const wordsA = normalizeWords(a);
      const wordsB = normalizeWords(b);
      if (!wordsA.length || !wordsB.length) return false;
      return wordsA.some(function (w) { return wordsB.indexOf(w) !== -1; });
    }

    if (!duplicateMatch && isLodging && startDt) {
      const dayDateById = {};
      days.forEach(function (d) { dayDateById[d.id] = d.date; });
      const lodgingStartMs = startDt.getTime();
      const lodgingEndMs = (endDt || startDt).getTime();
      // Overlapping dates alone are not a duplicate signal for lodging - the household
      // routinely books more than one real thing for the same dates (multiple rooms,
      // a companion's separate hotel, an unrelated "Home"/placeholder entry). Require a
      // plausible name relation to the booking's own provider before date overlap counts;
      // an exact confirmation match is already handled by the check above this one.
      duplicateMatch = existingAccommodations.find(function (a) {
        if (!providerNamesRelated(ex.provider_name, a.place_name)) return false;
        const aStart = toDate(dayDateById[a.start_day_id]);
        if (!aStart) return false;
        const aEnd = toDate(dayDateById[a.end_day_id]) || aStart;
        return overlaps(lodgingStartMs, lodgingEndMs, aStart.getTime(), aEnd.getTime());
      }) || existingReservations.find(function (r) {
        if (r.type !== 'hotel') return false;
        if (!providerNamesRelated(ex.provider_name, r.title)) return false;
        // A hotel-type reservation (the placeId-not-found fallback below) carries the full
        // stay in reservation_time/reservation_end_time - prefer that over day_id, which is
        // only ever a single check-in day and would under-match a multi-night stay. Fall
        // back to day_id for any older record created before reservation_time was added.
        const rStart = toDate(r.reservation_time);
        if (rStart) {
          const rEnd = toDate(r.reservation_end_time) || rStart;
          return overlaps(lodgingStartMs, lodgingEndMs, rStart.getTime(), rEnd.getTime());
        }
        const rDayDate = toDate(dayDateById[r.day_id]);
        if (!rDayDate) return false;
        const rDayEnd = toDate(dayDateById[r.end_day_id]) || rDayDate;
        return overlaps(lodgingStartMs, lodgingEndMs, rDayDate.getTime(), rDayEnd.getTime());
      });
      if (duplicateMatch) duplicateMatchReason = 'overlapping stay dates';
    }

    if (!duplicateMatch && expectedTransportType && startDt) {
      const startMs = startDt.getTime();
      const endMs = (endDt || startDt).getTime();
      duplicateMatch = existingReservations.find(function (r) {
        if (r.type !== expectedTransportType) return false;
        // Same rationale as the lodging overlap fallback above: two genuinely different
        // same-day bookings of the same transport type (e.g. two separate flights, or one
        // traveler's outbound flight and another's on the same day) are common, not a
        // duplicate - require a plausible name relation before date overlap counts; an
        // exact confirmation match is already handled by the check above this one.
        if (!providerNamesRelated(ex.provider_name, r.title)) return false;
        const rStart = toDate(r.reservation_time);
        if (!rStart) return false;
        const rEnd = toDate(r.reservation_end_time) || rStart;
        return overlaps(startMs, endMs, rStart.getTime(), rEnd.getTime());
      });
      if (duplicateMatch) duplicateMatchReason = 'same transport type with overlapping dates';
    }

    isDuplicate = Boolean(duplicateMatch);

    if (!isDuplicate) {
      const startDayId = await ensureDayId(startDateOnly);
      const endDayId = (await ensureDayId(endDateOnly)) || startDayId;

      if (ex.booking_type === 'flight' || ex.booking_type === 'transit' || ex.booking_type === 'cruise') {
        const transportTypeMap = { flight: 'flight', transit: 'train', cruise: 'cruise' };
        const transportType = transportTypeMap[ex.booking_type];
        const args = {
          tripId: tripId,
          type: transportType,
          title: (ex.provider_name || transportType) + (ex.confirmation_code ? ' (' + ex.confirmation_code + ')' : ''),
        };
        if (startDayId) args.start_day_id = startDayId;
        if (endDayId) args.end_day_id = endDayId;
        if (ex.start_datetime) args.reservation_time = ex.start_datetime;
        if (ex.end_datetime) args.reservation_end_time = ex.end_datetime;
        if (ex.confirmation_code) args.confirmation_number = ex.confirmation_code;
        if (costPlan && costPlan.linked) {
          args.price = costPlan.amount;
          args.budget_category = costPlan.category;
        }
        const stops = (ex.stops || []).filter(function (s) {
          return s && s.name && !/^cruising$|^at sea$|^day at sea$|^sea day$/i.test(s.name.trim());
        });
        if (stops.length > 1) {
          const endpoints = [];
          for (let i = 0; i < stops.length; i++) {
            const s = stops[i];
            const endpoint = {
              role: i === 0 ? 'from' : i === stops.length - 1 ? 'to' : 'stop',
              sequence: i,
              name: s.name,
              local_date: s.date || undefined,
            };
            const coords = await resolveCoords(sessionId, s.name);
            if (coords) {
              endpoint.lat = coords.lat;
              endpoint.lng = coords.lng;
            }
            endpoints.push(endpoint);
          }
          args.endpoints = endpoints;
        }
        createdBooking = await mcpTool(sessionId, 'create_transport', args);
        if (costPlan && !costPlan.linked) await recordBudgetItem(args.title, null);
      } else if (isLodging && startDayId && endDayId) {
        const searchQuery = [ex.provider_name, ex.destination_name || ex.destination_code]
          .filter(Boolean)
          .join(' ');
        let placeId = null;
        if (searchQuery) {
          const searchResult = await mcpTool(sessionId, 'search_place', { query: searchQuery });
          const places = searchResult.places || [];
          const best = places[0];
          if (best) {
            const placeArgs = {
              tripId: tripId,
              name: best.name || ex.provider_name || 'Hotel',
            };
            if (best.lat != null) placeArgs.lat = best.lat;
            if (best.lng != null) placeArgs.lng = best.lng;
            if (best.address) placeArgs.address = best.address;
            if (best.google_place_id) placeArgs.google_place_id = best.google_place_id;
            if (best.google_ftid) placeArgs.google_ftid = best.google_ftid;
            if (best.osm_id) placeArgs.osm_id = best.osm_id;
            const createdPlace = await mcpTool(sessionId, 'create_place', placeArgs);
            placeId = createdPlace.place ? createdPlace.place.id : createdPlace.id;
          } else {
            placeSearchNote = 'No place match found for "' + searchQuery + '"';
          }
        }
        if (placeId) {
          const accomArgs = {
            tripId: tripId,
            place_id: placeId,
            start_day_id: startDayId,
            end_day_id: endDayId,
          };
          const checkInTime = timeOnly(ex.start_datetime);
          const checkOutTime = timeOnly(ex.end_datetime);
          if (checkInTime) accomArgs.check_in = checkInTime;
          if (checkOutTime) accomArgs.check_out = checkOutTime;
          if (ex.confirmation_code) accomArgs.confirmation = ex.confirmation_code;
          if (ex.notes) accomArgs.notes = ex.notes;
          createdBooking = await mcpTool(sessionId, 'create_accommodation', accomArgs);
          // create_accommodation has no price field at all (unlike create_reservation/
          // create_transport), so its cost always goes through a separate budget item,
          // linked back to the place instead of the booking.
          if (costPlan) {
            await recordBudgetItem((ex.provider_name || 'Hotel') + (ex.confirmation_code ? ' (' + ex.confirmation_code + ')' : ''), placeId);
          }
          // Assign the place to every day of the stay, not just the accommodation record's
          // own date span - the day-by-day itinerary view (used for transport planning)
          // only shows what's assigned to each day.
          const startDayNum = dayNumberById(startDayId);
          const endDayNum = dayNumberById(endDayId);
          if (startDayNum != null && endDayNum != null) {
            const stayDayIds = days
              .filter(function (d) { return d.day_number != null && d.day_number >= startDayNum && d.day_number <= endDayNum; })
              .map(function (d) { return d.id; });
            for (const stayDayId of stayDayIds) {
              await mcpTool(sessionId, 'assign_place_to_day', { tripId: tripId, dayId: stayDayId, placeId: placeId });
            }
          }
} else {
          const args = {
            tripId: tripId,
            type: 'hotel',
            title: (ex.provider_name || 'Hotel') + (ex.confirmation_code ? ' (' + ex.confirmation_code + ')' : ''),
          };
          if (startDayId) args.day_id = startDayId;
          if (ex.start_datetime) args.reservation_time = ex.start_datetime;
          if (ex.end_datetime) args.reservation_end_time = ex.end_datetime;
          if (ex.confirmation_code) args.confirmation_number = ex.confirmation_code;
          if (ex.notes) args.notes = ex.notes;
          if (placeSearchNote) args.notes = (args.notes ? args.notes + ' - ' : '') + placeSearchNote;
          if (costPlan && costPlan.linked) {
            args.price = costPlan.amount;
            args.budget_category = costPlan.category;
          }
          createdBooking = await mcpTool(sessionId, 'create_reservation', args);
          if (costPlan && !costPlan.linked) await recordBudgetItem(args.title, null);
        }
      } else {
        const typeMap = { lodging: 'hotel', rental_car: 'other', restaurant: 'restaurant', activity: 'activity', general: 'other' };
        const args = {
          tripId: tripId,
          type: typeMap[ex.booking_type] || 'other',
          title: (ex.provider_name || ex.booking_type || 'Booking') + (ex.confirmation_code ? ' (' + ex.confirmation_code + ')' : ''),
        };
        if (startDayId) args.day_id = startDayId;
        if (ex.start_datetime) args.reservation_time = ex.start_datetime;
        if (ex.end_datetime) args.reservation_end_time = ex.end_datetime;
        if (ex.confirmation_code) args.confirmation_number = ex.confirmation_code;
        if (ex.notes) args.notes = ex.notes;
        if (costPlan && costPlan.linked) {
          args.price = costPlan.amount;
          args.budget_category = costPlan.category;
        }
        createdBooking = await mcpTool(sessionId, 'create_reservation', args);
        if (costPlan && !costPlan.linked) await recordBudgetItem(args.title, null);
      }
    }
  } catch (e) {
    trekError = e.message || String(e);
  }
}

const execRef = 'n8n-exec-' + ($execution && $execution.id ? $execution.id : 'unknown');

const costLine = costPlan
  ? '\nCost: ' + costPlan.amount.toFixed(2) + ' ' + (costPlan.currency || '(trip currency)') + (costPlan.linked ? '' : ' - recorded as a separate expense, not shown on the booking')
  : '';
const costWarning = costError ? '\n\nWarning: ' + costError : '';

let notifySubject;
let notifyText;
if (extractionError) {
  notifySubject = 'Could not process trip email: ' + (item.subject || 'no subject');
  notifyText =
    'I could not process this email automatically.\n\n' +
    'Error: ' + extractionError + '\n\n' +
    'Original subject: ' + (item.subject || 'n/a') + '\n' +
    'From: ' + (item.mimeFrom || 'n/a') + '\n\n' +
    'Please add this to Trek manually if it is a real booking.\n\n' +
    'Ref: ' + execRef;
} else if (trekError) {
  notifySubject = 'Trek add failed: ' + (ex.provider_name || ex.booking_type || 'Booking');
  notifyText =
    'I could not add this to Trek automatically - please add it manually.\n\n' +
    'Error: ' + trekError + '\n\n' +
    'Type: ' + (ex.booking_type || 'unknown') + '\n' +
    'Provider: ' + (ex.provider_name || 'n/a') + '\n' +
    'Confirmation: ' + (ex.confirmation_code || 'n/a') +
    (pdfExtractionWarning ? '\n\nWarning: ' + pdfExtractionWarning : '') +
    '\n\nRef: ' + execRef;
} else if (isDuplicate) {
  const matchedTitle = duplicateMatch ? duplicateMatch.title || duplicateMatch.reservation_title || duplicateMatch.place_name || 'existing record' : 'existing record';
  const matchedConfirmation = duplicateMatch ? duplicateMatch.confirmation_number || duplicateMatch.confirmation || 'n/a' : 'n/a';
  notifySubject = 'Already in Trek: ' + (ex.provider_name || ex.booking_type || 'Booking');
  notifyText =
    'This booking was already in Trek (matched by ' + (duplicateMatchReason || 'confirmation code') + ') - no duplicate created.\n\n' +
    'Matched: ' + matchedTitle + ' (confirmation: ' + matchedConfirmation + ')\n' +
    'Trip: https://${TREK_SUBDOMAIN}.${SECRET_DOMAIN}/trips/' + tripId + '\n' +
    'Type: ' + (ex.booking_type || 'unknown') + '\n' +
    'Provider: ' + (ex.provider_name || 'n/a') + '\n' +
    'Confirmation: ' + (ex.confirmation_code || 'n/a') +
    (pdfExtractionWarning ? '\n\nWarning: ' + pdfExtractionWarning : '') +
    '\n\nRef: ' + execRef;
} else {
  notifySubject = 'Added to Trek: ' + (ex.provider_name || ex.booking_type || 'Booking');
  notifyText =
    (createdNewTrip ? 'Created a new trip and added this booking.' : 'Added this booking to an existing trip.') + '\n\n' +
    'Trip: https://${TREK_SUBDOMAIN}.${SECRET_DOMAIN}/trips/' + tripId + '\n' +
    'Type: ' + (ex.booking_type || 'unknown') + '\n' +
    'Provider: ' + (ex.provider_name || 'n/a') + '\n' +
    'Confirmation: ' + (ex.confirmation_code || 'n/a') +
    costLine +
    (pdfExtractionWarning ? '\n\nWarning: ' + pdfExtractionWarning : '') +
    costWarning +
    '\n\nRef: ' + execRef;
}

return [
  {
    json: Object.assign({}, item, {
      trekTripId: tripId,
      trekCreatedNewTrip: createdNewTrip,
      trekIsDuplicate: isDuplicate,
      trekDuplicateMatchReason: duplicateMatchReason,
      trekCreatedBooking: createdBooking,
      trekPlaceSearchNote: placeSearchNote,
      trekCostPlan: costPlan,
      trekCostError: costError,
      trekError: trekError,
      extractionError: extractionError,
      notifySubject: notifySubject,
      notifyText: notifyText,
    }),
  },
];
